for (let hour = 0; hour < 24; hour++) timeValues.push(Date.UTC(2025, 5, 9 + (hour % 7), hour), Date.UTC(2025, 5, 9, hour, 59, 59, 999));
for (const transition of [Date.UTC(2024, 2, 31, 1), Date.UTC(2024, 9, 27, 1)]) timeValues.push(transition - 1, transition, transition + 3_600_000 - 1, transition + 3_600_000);

const numberValues: number[] = [122568415397312.47, NaN, Infinity, -Infinity, 0, -0, 2 ** 53, 2 ** 53 - 1, -(2 ** 53 - 1), 2 ** 31, 1e21, 1e-7, 1e-6, 0.1 + 0.2, 1 / 3, 2 / 3];
for (let power = 1; power < 1e17; power *= 10) numberValues.push(power, power - 1, power + 1, -power, power * 5, power / 2);
for (const numerator of [1, 4, 5, 6, 9, 15, 25, 35, 45, 49, 50, 51, 95, 99, 105, 125, 375, 995, 999, 1005, 1255, 2675, 8345, 9995])
  for (const scale of [10, 100, 1000, 10000]) numberValues.push(numerator / scale, -numerator / scale, 1 + numerator / scale, 1234567 + numerator / scale);

function compare(name: string, cases: [(value: any) => string, string][], values: number[], twinOf: (locale: string, options: any) => { format(value: any): string }) {
  let comparisons = 0;
  let differences = 0;
  for (const [format, text] of cases) {
    const [locale, options] = JSON.parse(text);
    const twin = twinOf(locale, options ?? undefined);
    for (const value of values) {
      comparisons++;
      const got = say(() => format(value));
      const expected = say(() => twin.format(value));
      if (got !== expected && ++differences <= 10) console.log("DIFFERENT", text, Object.is(value, -0) ? "-0" : value, JSON.stringify(got), JSON.stringify(expected));
    }
  }
  console.log(name + ": " + cases.length + " formatters, " + comparisons + " comparisons, " + differences + " differences");
}
compare("dates", dateCases, timeValues, (locale, options) => new Intl.DateTimeFormat(locale, options));
compare("numbers", numberCases, numberValues, (locale, options) => new Intl.NumberFormat(locale, options));
